BEGIN;
ALTER TABLE "Permission" DROP CONSTRAINT "Permission_catalog_check";
ALTER TABLE "Permission" ADD CONSTRAINT "Permission_catalog_check" CHECK ("key" IN ('payroll:view_details','task:create','task:assign','task:view','task:update','task:review','task:report','inventory:view','inventory:manage','inventory:receive','inventory:checkout','inventory:sales:view','inventory:report','business:update','members:invite','members:remove','members:update_role','members:update_status','members:view','roles:view','roles:create','roles:update','roles:delete','roles:assign','payments:create','payments:view','payments:view_own','payments:approve','payments:cancel','providers:create','providers:update','providers:view','invoices:create','employee_lists:create','employee_lists:view','employee_lists:update','employee_lists:archive','employees:create','employees:view','employees:update','employees:archive','employees:verify','invoices:view','reports:view','audit_logs:view','employees:view_own','policies:view','policies:create','policies:update','policies:archive','policies:assign','policies:view_audit','policies:reconcile','integrations:view','integrations:manage'));
CREATE OR REPLACE FUNCTION protect_system_permissions() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE assigned "Role"%ROWTYPE; previous "Role"%ROWTYPE;
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') THEN
   SELECT * INTO previous FROM "Role" WHERE "id"=OLD."roleId";
   IF previous."type"='system' THEN RAISE EXCEPTION 'System permission assignments cannot be edited or removed'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 SELECT * INTO assigned FROM "Role" WHERE "id"=NEW."roleId";
 IF assigned."type"='system' THEN
   IF TG_TABLE_NAME='RoleDeniedPermission' THEN RAISE EXCEPTION 'System roles have no explicit denials'; END IF;
   IF NOT ((assigned."key" IN ('owner','admin','finance_manager') AND NEW."permission"='payroll:view_details') OR (assigned."key"='owner' AND NEW."permission" IN ('task:create','task:assign','task:view','task:update','task:review','task:report','inventory:view','inventory:manage','inventory:receive','inventory:checkout','inventory:sales:view','inventory:report','business:update','members:invite','members:remove','members:update_role','members:update_status','members:view','roles:view','roles:create','roles:update','roles:delete','roles:assign','payments:create','payments:view','payments:view_own','payments:approve','payments:cancel','providers:create','providers:update','providers:view','invoices:create','employee_lists:create','employee_lists:view','employee_lists:update','employee_lists:archive','employees:create','employees:view','employees:update','employees:archive','employees:verify','invoices:view','reports:view','audit_logs:view','employees:view_own','policies:view','policies:create','policies:update','policies:archive','policies:assign','policies:view_audit','policies:reconcile','integrations:view','integrations:manage')) OR (assigned."key"='admin' AND NEW."permission" IN ('task:create','task:assign','task:view','task:update','task:review','task:report','inventory:view','inventory:manage','inventory:receive','inventory:checkout','inventory:sales:view','inventory:report','members:invite','members:view','members:update_status','payments:create','payments:approve','payments:view','providers:create','providers:update','invoices:create','invoices:view','reports:view','audit_logs:view','employee_lists:create','employee_lists:view','employee_lists:update','employee_lists:archive','employees:create','employees:view','employees:update','employees:archive','employees:verify','integrations:view','integrations:manage')) OR (assigned."key"='finance_manager' AND NEW."permission" IN ('inventory:view','inventory:checkout','inventory:sales:view','inventory:report','payments:create','payments:approve','payments:view','providers:create','invoices:create','invoices:view','reports:view','employee_lists:create','employee_lists:view','employee_lists:update','employees:create','employees:view','employees:update','employees:verify','members:view')) OR (assigned."key"='accountant' AND NEW."permission" IN ('inventory:view','inventory:sales:view','inventory:report','payments:view','invoices:view','reports:view','members:view','employee_lists:view','employees:view')) OR (assigned."key"='employee' AND NEW."permission" IN ('employees:view_own','members:view','employee_lists:view','reports:view')) OR (assigned."key"='contributor' AND NEW."permission" IN ('payments:create','members:view','payments:view_own')) OR (assigned."key"='viewer' AND NEW."permission" IN ('payments:view','invoices:view','members:view','reports:view'))) THEN RAISE EXCEPTION 'Permission is not granted to this system role'; END IF;
 END IF;
 RETURN NEW;
END $$;
INSERT INTO "Permission" ("key") VALUES ('payroll:view_details') ON CONFLICT DO NOTHING;
INSERT INTO "RolePermission" ("roleId","permission")
SELECT "id",'payroll:view_details' FROM "Role"
WHERE "type"='system' AND "businessId" IS NULL AND "key" IN ('owner','admin','finance_manager')
ON CONFLICT DO NOTHING;
COMMIT;
